76	    /**
77	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
78	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
79	     */
80	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
81	
82	    /**
83	     * Domains known to hand out disposable/throwaway mailboxes. An owner whose email domain is on
84	     * this blocklist is rejected: such addresses cannot be relied on for contacting the owner.
85	     */
86	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
87	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
88	
89	    /** Dedicated audit logger; create side-effects are recorded here so they can be observed independently. */
90	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
91	
92	    /** Request header carrying the client-supplied idempotency key for owner creation. */
93	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
94	
95	    /**
96	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that create originally
97	     * produced for it. A repeated create carrying a key found here returns that same owner instead of
98	     * creating a duplicate, making owner creation idempotent with respect to the key.
99	     */
100	    private final Map<String, Integer> ownersByIdempotencyKey = new ConcurrentHashMap<>();
