120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
123	        Collection<Owner> owners;
124	        if (lastName != null) {
125	            owners = this.clinicService.findOwnerByLastName(lastName);
126	        } else {
127	            owners = this.clinicService.findAllOwners();
128	        }
129	        if (owners.isEmpty()) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        List<OwnerDto> ownerDtos = owners.stream()
133	            .map(this::toOwnerDtoWithBulkWarning)
134	            .toList();
135	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
136	    }
