215	    /**
216	     * Returns the {@code Idempotency-Key} header of the request in progress, or {@code null} when the
217	     * header is absent, blank, or there is no active servlet request. The generated {@link OwnersApi}
218	     * signature carries no header parameter, so it is read from the current request context.
219	     */
220	    private static String currentIdempotencyKey() {
221	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
222	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
223	            if (key != null && !key.isBlank()) {
224	                return key;
225	            }
226	        }
227	        return null;
228	    }
