323	    /**
324	     * Builds the owner's customer code as {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
325	     * region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'}) via
326	     * {@link OwnerMapper#toRegion}, and {@code HASH8} is the first 8 upper-case hex characters of the
327	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}).
328	     *
329	     * <p>When the computed code collides with an existing owner's {@code customerCode}, it is
330	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it
331	     * unique (e.g. {@code NSW-1A2B3C4D-2}); the de-duplicated code is returned. Absent a collision the
332	     * base region-and-hash code is returned unchanged.
333	     *
334	     * @param owner the owner being created, with its region-determining postcode and city populated
335	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
336	     * @return the (de-duplicated) region-and-hash customer code for the owner being created
337	     */
338	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
339	        String region = ownerMapper.toRegion(owner);
340	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
341	        String baseCode = region + "-" + hash8;
342	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
343	            .map(Owner::getCustomerCode)
344	            .filter(java.util.Objects::nonNull)
345	            .collect(java.util.stream.Collectors.toSet());
346	        if (!existingCodes.contains(baseCode)) {
347	            return baseCode;
348	        }
349	        int n = 2;
350	        while (existingCodes.contains(baseCode + "-" + n)) {
351	            n++;
352	        }
353	        return baseCode + "-" + n;
354	    }
355	
356	    /**
357	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
358	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
359	     */
360	    private static String sha256Hex8(String value) {
361	        try {
362	            byte[] digest = MessageDigest.getInstance("SHA-256")
363	                .digest(value.getBytes(StandardCharsets.UTF_8));
364	            StringBuilder sb = new StringBuilder();
365	            for (byte b : digest) {
366	                sb.append(String.format("%02X", b));
367	            }
368	            return sb.substring(0, 8);
369	        }
370	        catch (NoSuchAlgorithmException e) {
371	            throw new IllegalStateException("SHA-256 not available", e);
372	        }
373	    }
