375	    /**
376	     * Counts the existing owners (those already persisted before this create) whose first and last
377	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
378	     * the new owner as its {@code namesakeCount} and echoed back on reads.
379	     *
380	     * @param firstName the incoming owner's first name (already validated non-blank)
381	     * @param lastName the incoming owner's last name (already validated non-blank)
382	     * @return the number of existing namesakes sharing both names case-insensitively
383	     */
384	    private int countNamesakes(String firstName, String lastName) {
385	        return (int) this.clinicService.findAllOwners().stream()
386	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
387	                && lastName.equalsIgnoreCase(existing.getLastName()))
388	            .count();
389	    }
