391	    /**
392	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
393	     * whitespace-only), so the caller can reject the request listing every offending field.
394	     */
395	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
396	        if (value == null || value.isBlank()) {
397	            missingFields.add(fieldName);
398	        }
399	    }
