401	    /**
402	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
403	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
404	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
405	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
406	     * {@code "+61412345678"}.
407	     *
408	     * @param telephone the raw telephone value from the request
409	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
410	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
411	     */
412	    private static String normalizeTelephone(String telephone) {
413	        String e164 = toE164(telephone);
414	        if (e164 == null) {
415	            throw new InvalidFieldValueException("telephone",
416	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
417	        }
418	        return e164;
419	    }
420	
421	    /**
422	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
423	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
424	     * owners' stored numbers when detecting duplicates.
425	     */
426	    private static String toE164(String telephone) {
427	        if (telephone == null) {
428	            return null;
429	        }
430	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
431	        String digits;
432	        if (cleaned.startsWith("+")) {
433	            digits = cleaned.substring(1);
434	        } else {
435	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
436	            digits = "61" + national;
437	        }
438	        if (!digits.matches("[0-9]{8,15}")) {
439	            return null;
440	        }
441	        if (!hasValidNationalLength(digits)) {
442	            return null;
443	        }
444	        return "+" + digits;
445	    }
446	
447	    /**
448	     * Checks the national-number length against the country code for the country codes that pin one.
449	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
450	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
451	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
452	     */
453	    private static boolean hasValidNationalLength(String digits) {
454	        if (digits.startsWith("61")) {
455	            return digits.length() - 2 == 9;
456	        }
457	        if (digits.startsWith("1")) {
458	            return digits.length() - 1 == 10;
459	        }
460	        return true;
461	    }
462	
463	    /**
464	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
465	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
466	     *
467	     * @param email the raw email value from the request (already known to be non-null)
468	     * @return the lower-cased email to be stored and returned
469	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
470	     */
471	    private static String normalizeEmail(String email) {
472	        String trimmed = email.trim();
473	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
474	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
475	        }
476	        String canonical = trimmed.toLowerCase(Locale.ROOT);
477	        String domain = canonical.substring(canonical.indexOf('@') + 1);
478	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
479	            throw new InvalidFieldValueException("email", "Email must not use a disposable-domain address");
480	        }
481	        return canonical;
482	    }
483	
484	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
485	    private static final int MAX_OWNERS_PER_CITY = 50;
486	
487	    /**
488	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
489	     * owners, comparing city names case-insensitively. Callers reach this only once {@code city} has
490	     * been validated non-blank.
491	     *
492	     * @param city the incoming owner's city (already validated non-blank)
493	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
494	     */
495	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
496	    private static final int MAX_OWNERS_PER_DAY = 100;
497	
498	    /**
499	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
500	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
501	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
502	     * date rolled forward to a business day), so this caps the number that may be created per day.
503	     *
504	     * @param businessDay the adjusted business-day registration date of the owner being created
505	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
506	     */
507	    /**
508	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
509	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
510	     */
511	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
512	
513	    /**
514	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
515	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
516	     * owner's registration date, otherwise {@code false}.
517	     *
518	     * @param owner the owner to map
519	     * @return the owner DTO with its bulk-signup warning flag populated
520	     */
521	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
522	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
523	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
524	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
525	        ownerDto.setMembershipPoints(points);
526	        ownerDto.setMembershipLevel(capMembershipLevel(owner, OwnerMapper.membershipLevelFor(points)));
527	        return ownerDto;
528	    }
529	
530	    /**
531	     * Caps the owner's {@code membershipLevel} so it cannot exceed one above the current maximum
532	     * membership level among the other members of its household (existing owners carrying the same
533	     * {@code householdId}, excluding the owner itself and any soft-deleted owner). When the household
534	     * has no other member — including when the owner has no {@code householdId} — no cap applies and
535	     * {@code level} is returned unchanged. Each household member's level is its own base level (points
536	     * mapped to a level for its real household size), so the cap does not depend on other capped
537	     * values.
538	     *
539	     * @param owner the owner whose membership level is being computed
540	     * @param level the owner's uncapped membership level derived from its membership points
541	     * @return the membership level capped at {@code maxHouseholdMemberLevel + 1}, or {@code level}
542	     *         when the owner has no other household member
543	     */
544	    private int capMembershipLevel(Owner owner, int level) {
545	        String householdId = owner.getHouseholdId();
546	        if (householdId == null) {
547	            return level;
548	        }
549	        Integer maxMemberLevel = this.clinicService.findAllOwners().stream()
550	            .filter(existing -> !isDeleted(existing))
551	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
552	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
553	            .map(this::membershipLevelForOwner)
554	            .max(Integer::compareTo)
555	            .orElse(null);
556	        if (maxMemberLevel == null) {
557	            return level;
558	        }
559	        return Math.min(level, maxMemberLevel + 1);
560	    }
561	
562	    /**
563	     * Computes an existing household member's membership level: its membership points for its real
564	     * household size mapped to the numeric level. Used to establish the household's current maximum
565	     * level when capping a new owner's level.
566	     */
567	    private int membershipLevelForOwner(Owner owner) {
568	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
569	        return OwnerMapper.membershipLevelFor(points);
570	    }
571	
572	    /**
573	     * Returns the number of owners sharing the given {@code householdId} (the household's size),
574	     * counting every existing owner that carries the same {@code householdId}. Returns {@code 0} when
575	     * {@code householdId} is {@code null}, since an owner with no postcode has no household key and so
576	     * no household.
577	     *
578	     * @param householdId the owner's computed household identifier, or {@code null} when absent
579	     * @return the number of owners in the household
580	     */
581	    private int householdSize(String householdId) {
582	        if (householdId == null) {
583	            return 0;
584	        }
585	        return (int) this.clinicService.findAllOwners().stream()
586	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
587	            .count();
588	    }
589	
590	    /**
591	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
592	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
593	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
594	     */
595	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
596	        if (registrationDate == null) {
597	            return false;
598	        }
599	        long registeredThatDay = this.clinicService.findAllOwners().stream()
600	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
601	            .count();
602	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
603	    }
604	
605	    private void requireDailyLimitNotReached(LocalDate businessDay) {
606	        long registeredThatDay = this.clinicService.findAllOwners().stream()
607	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
608	            .count();
609	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
610	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
611	        }
612	    }
613	
614	    /**
615	     * Fixed list of public holidays. A registration date landing on one of these dates is rolled
616	     * forward, just like a weekend, until it reaches a non-holiday business day.
617	     */
618	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
619	        LocalDate.of(2026, 1, 1),
620	        LocalDate.of(2026, 1, 26),
621	        LocalDate.of(2026, 4, 25),
622	        LocalDate.of(2026, 12, 25),
623	        LocalDate.of(2026, 12, 28));
624	
625	    /**
626	     * Rolls {@code date} forward to a business day: while it falls on a Saturday, Sunday, or a listed
627	     * public holiday it advances one day at a time until it reaches a non-holiday weekday. Applied to
628	     * the effective registration date (whether supplied in the request or defaulted to the server date)
629	     * so a weekend or holiday registration is recorded on the next business day, and every value derived
630	     * from the registration date uses the adjusted date.
631	     *
632	     * @param date the effective registration date (supplied or defaulted), never {@code null}
633	     * @return the same date, or the next non-holiday business day when {@code date} is a weekend or holiday
634	     */
635	    private static LocalDate toBusinessDay(LocalDate date) {
636	        LocalDate adjusted = date;
637	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
638	            adjusted = adjusted.plusDays(1);
639	        }
640	        return adjusted;
641	    }
642	
643	    /** Whether {@code date} falls on a Saturday or Sunday. */
644	    private static boolean isWeekend(LocalDate date) {
645	        DayOfWeek day = date.getDayOfWeek();
646	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
647	    }
648	
649	    /** Matches a well-formed postcode: exactly four decimal digits. */
650	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
651	
652	    /**
653	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
654	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
655	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
656	     * present here and accepts any well-formed postcode.
657	     */
658	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
659	        "NSW", new int[] {2000, 2099},
660	        "VIC", new int[] {3000, 3099},
661	        "QLD", new int[] {4000, 4099});
662	
663	    /**
664	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
665	     * optional, so the request contract stays backward-compatible). When present it must be exactly
666	     * four digits and, for a city whose region is known, fall within that region's inclusive range
667	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
668	     * postcode. A malformed or out-of-range value is rejected with a 400.
669	     *
670	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
671	     * @param city the owner's city, used to look up the region whose range constrains the postcode
672	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
673	     */
674	    private void validatePostcode(String postcode, String city) {
675	        if (postcode == null) {
676	            return;
677	        }
678	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
679	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
680	        }
681	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
682	        int[] range = REGION_POSTCODES.get(region);
683	        if (range == null) {
684	            return;
685	        }
686	        int value = Integer.parseInt(postcode);
687	        if (value < range[0] || value > range[1]) {
688	            throw new InvalidFieldValueException("postcode",
689	                "Postcode must be valid for the city's region " + region);
690	        }
691	    }
692	
693	    /**
694	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
695	     * date defaults to the server date). When present it must not be later than the current server
696	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
697	     *
698	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
699	     * @throws InvalidFieldValueException if the supplied date is later than the server date
700	     */
701	    private void validateRegistrationDate(LocalDate registrationDate) {
702	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
703	            throw new InvalidFieldValueException("registrationDate",
704	                "Registration date must not be later than the current date");
705	        }
706	    }
707	
708	    private void requireCityBelowCapacity(String city) {
709	        long cityOwners = this.clinicService.findAllOwners().stream()
710	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
711	            .count();
712	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
713	            throw new CityAtCapacityException(city);
714	        }
715	    }
716	
717	    /**
718	     * Rejects the request when the incoming owner's derived {@code identityKey} exactly matches that
719	     * of any existing owner. The key ({@code normalizedTelephone + '|' + (email or empty) + '|' +
720	     * (householdId or empty)}) is the single consolidated duplicate-detection key that replaces the
721	     * former separate telephone, email and household checks. Because the telephone is part of the
722	     * key, two members of the same household (same {@code householdId}) with different telephones
723	     * have different keys and are both allowed; only an exact full-key match is a duplicate. The key
724	     * is derived identically for the incoming and existing owners via {@link OwnerMapper#toIdentityKey}.
725	     *
726	     * @param owner the incoming owner, with its normalized telephone, email and household identifier
727	     *              already populated
728	     * @throws DuplicateIdentityException if another owner already has this exact identity key
729	     */
730	    private void requireUniqueIdentity(Owner owner) {
731	        String identityKey = ownerMapper.toIdentityKey(owner);
732	        boolean taken = this.clinicService.findAllOwners().stream()
733	            .filter(existing -> !isDeleted(existing))
734	            .map(ownerMapper::toIdentityKey)
735	            .anyMatch(identityKey::equals);
736	        if (taken) {
737	            throw new DuplicateIdentityException(identityKey);
738	        }
739	    }
740	
741	    /**
742	     * Returns whether an existing owner has been soft-deleted. A soft-deleted owner retains its row
743	     * but is ignored by the create endpoint's duplicate and identity checks, so a normally-blocking
744	     * duplicate is allowed when the only matching owner has been deleted.
745	     */
746	    private static boolean isDeleted(Owner owner) {
747	        return Boolean.TRUE.equals(owner.getDeleted());
748	    }
749	
750	    /**
751	     * Flags the incoming owner as a possible (soft) duplicate. Called after the hard-duplicate and
752	     * household-duplicate checks have passed, so the owner is known not to be a rejected duplicate.
753	     * When an existing owner shares this owner's household (same computed {@code householdId}) but
754	     * carries a different telephone, the owner is a possible duplicate: {@code possibleDuplicate} is
755	     * set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest such
756	     * owner by id when more than one matches). Otherwise both are cleared. A declared household member
757	     * ({@code sharesHousehold} true) is never flagged: it is a deliberate member, not a suspected
758	     * duplicate. An owner with no {@code householdId} never matches, since it shares no household.
759	     *
760	     * @param owner the incoming owner, with its computed {@code householdId} and telephone populated
761	     * @param sharesHousehold whether the request opted in as a declared household member
762	     */
763	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
764	        owner.setPossibleDuplicate(false);
765	        owner.setPossibleDuplicateOf(null);
766	        if (sharesHousehold) {
767	            return;
768	        }
769	        String householdId = owner.getHouseholdId();
770	        if (householdId == null) {
771	            return;
772	        }
773	        String telephone = owner.getTelephone();
774	        this.clinicService.findAllOwners().stream()
775	            .filter(existing -> householdId.equals(existing.getHouseholdId())
776	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
777	            .min(java.util.Comparator.comparing(Owner::getId))
778	            .ifPresent(match -> {
779	                owner.setPossibleDuplicate(true);
780	                owner.setPossibleDuplicateOf(match.getId());
781	            });
782	    }
783	
784	    /**
785	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
786	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
787	     * comparisons are case-insensitive.
788	     */
789	    private static String normalizeForHousehold(String value) {
790	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
791	    }
792	
793	    /**
794	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
795	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
796	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
797	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
798	     * value normalizes to the empty string, so the required-field check rejects an address that is
799	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
800	     *
801	     * @param address the raw address value from the request (may be {@code null})
802	     * @return the normalized address, or the empty string when blank after normalization
803	     */
804	    private static String normalizeAddress(String address) {
805	        if (address == null) {
806	            return "";
807	        }
808	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
809	        if (collapsed.isEmpty()) {
810	            return "";
811	        }
812	        String[] tokens = collapsed.split(" ");
813	        StringBuilder sb = new StringBuilder();
814	        for (String token : tokens) {
815	            String expanded = switch (token) {
816	                case "ST" -> "STREET";
817	                case "RD" -> "ROAD";
818	                case "AVE" -> "AVENUE";
819	                default -> token;
820	            };
821	            if (sb.length() > 0) {
822	                sb.append(' ');
823	            }
824	            sb.append(expanded);
825	        }
826	        return sb.toString();
827	    }
828	
829	    /**
830	     * Composes the stored/returned {@code address} from the normalized structured lines: the
831	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
832	     * appended when {@code addressLine2} is present (non-empty). Both arguments are already
833	     * normalized via {@link #normalizeAddress(String)}.
834	     *
835	     * @param normalizedAddressLine1 the normalized first address line (non-empty)
836	     * @param normalizedAddressLine2 the normalized second address line, or the empty string when absent
837	     * @return the composed address string
838	     */
839	    private static String composeAddress(String normalizedAddressLine1, String normalizedAddressLine2) {
840	        if (normalizedAddressLine2.isEmpty()) {
841	            return normalizedAddressLine1;
842	        }
843	        return normalizedAddressLine1 + " " + normalizedAddressLine2;
844	    }
845	
846	    /**
847	     * Derives the stable household identifier for an owner from its last name and postcode as the
848	     * upper-cased first 12 hex characters of the SHA-256 digest of
849	     * {@code normalizedLastName + '|' + postcode}, where the last name is normalized (trimmed,
850	     * internal whitespace collapsed, lower-cased) so casing and spacing do not affect it. Because the
851	     * identifier is a deterministic function of the normalized last name and postcode, owners that
852	     * share a last name and postcode share the identifier automatically — no back-fill or opt-in is
853	     * required. Returns {@code null} when no postcode is present, since the household is keyed on the
854	     * postcode and there is then nothing to key on.
855	     *
856	     * @param lastName the owner's last name (already validated non-blank)
857	     * @param postcode the owner's postcode (a validated 4-digit value, or {@code null} when absent)
858	     * @return the 12-hex-character household identifier, or {@code null} when no postcode is present
859	     */
860	    private static String householdIdFor(String lastName, String postcode) {
861	        if (postcode == null || postcode.isBlank()) {
862	            return null;
863	        }
864	        String normalizedLastName = normalizeForHousehold(lastName);
865	        try {
866	            byte[] digest = MessageDigest.getInstance("SHA-256")
867	                .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
868	            StringBuilder sb = new StringBuilder();
869	            for (byte b : digest) {
870	                sb.append(String.format("%02X", b));
871	            }
872	            return sb.substring(0, 12);
873	        }
874	        catch (NoSuchAlgorithmException e) {
875	            throw new IllegalStateException("SHA-256 not available", e);
876	        }
877	    }
878	}
