353	     * {@code 2} when a non-blank email is present, plus {@code 1} when the owner has no namesakes
354	     * ({@code namesakeCount} is 0), plus {@code 2} when {@code householdSize} is {@code 3} or more,
355	     * plus {@code 3} for a tenure of one or more elapsed fiscal years (each starting 1 July) between
356	     * the {@code registrationDate} and today.
357	     *
358	     * @param owner the owner whose points are computed, never {@code null}
359	     * @param householdSize the number of owners sharing the owner's household
360	     * @return the owner's membership points
361	     */
362	    static int membershipPointsFor(Owner owner, int householdSize) {
363	        int points = 0;
364	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
365	        if (hasEmail) {
366	            points += 2;
367	        }
368	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
369	        if (noNamesakes) {
370	            points += 1;
371	        }
372	        if (householdSize >= 3) {
373	            points += 2;
374	        }
375	        boolean tenured = owner.getRegistrationDate() != null
376	            && fiscalYear(LocalDate.now()) - fiscalYear(owner.getRegistrationDate()) >= 1;
377	        if (tenured) {
378	            points += 3;
379	        }
380	        return points;
381	    }
