383	    /**
384	     * Maps membership points to the numeric membership level: level {@code 1} for {@code 0-1} points,
385	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
386	     *
387	     * @param points the owner's membership points
388	     * @return the corresponding membership level (1-4)
389	     */
390	    static int membershipLevelFor(int points) {
391	        if (points <= 1) {
392	            return 1;
393	        }
394	        if (points <= 3) {
395	            return 2;
396	        }
397	        if (points <= 5) {
398	            return 3;
399	        }
400	        return 4;
401	    }
