403	    /**
404	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
405	     * contained in the owner's {@code customerCode}. Returns {@code null} when the customer code is
406	     * absent.
407	     */
408	    @Named("toCheckDigit")
409	    default Integer toCheckDigit(Owner owner) {
410	        if (owner == null || owner.getCustomerCode() == null) {
411	            return null;
412	        }
413	        int sum = 0;
414	        boolean dbl = true;
415	        String code = owner.getCustomerCode();
416	        for (int i = code.length() - 1; i >= 0; i--) {
417	            char c = code.charAt(i);
418	            if (c < '0' || c > '9') {
419	                continue;
420	            }
421	            int d = c - '0';
422	            if (dbl) {
423	                d *= 2;
424	                if (d > 9) {
425	                    d -= 9;
426	                }
427	            }
428	            sum += d;
429	            dbl = !dbl;
430	        }
431	        return (10 - (sum % 10)) % 10;
432	    }
