/**
 * Derives the owner's duplicate-detection {@code identityKey}: the single key that consolidates
 * the former separate telephone, email and household checks. It is the lower-case, 64-character
 * SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)},
 * where {@code lowerEmail} is the email trimmed and lower-cased (or the empty string when absent)
 * and {@code soundex(lastName)} is the American Soundex code of the owner's last name. Because the
 * telephone is part of the key, two owners with the same last name (same soundex) and postcode but
 * different telephones have different identity keys; only an exact full-key match is a duplicate.
 */
@Named("toIdentityKey")
default String toIdentityKey(Owner owner) {
    if (owner == null) {
        return null;
    }
    String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
    String email = owner.getEmail() == null ? "" : owner.getEmail().trim().toLowerCase(java.util.Locale.ROOT);
    String soundex = soundex(owner.getLastName());
    return sha256Hex(telephone + "|" + email + "|" + soundex);
}

/**
 * Returns the full lower-case (64-character) SHA-256 hex digest of {@code value}'s UTF-8 bytes.
 * Deterministic, so the same input always yields the same digest.
 */
static String sha256Hex(String value) {
    try {
        byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
            .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
        StringBuilder sb = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
    catch (java.security.NoSuchAlgorithmException e) {
        throw new IllegalStateException("SHA-256 not available", e);
    }
}

/**
 * Computes the American Soundex code of {@code name}: the retained first letter followed by three
 * digits encoding the remaining consonants ({@code b,f,p,v->1}; {@code c,g,j,k,q,s,x,z->2};
 * {@code d,t->3}; {@code l->4}; {@code m,n->5}; {@code r->6}). Adjacent letters sharing a code
 * collapse to one digit (letters separated by {@code h} or {@code w} are treated as adjacent,
 * while vowels — {@code a,e,i,o,u,y} — break the run), and the result is right-padded with zeros
 * and truncated to four characters (e.g. {@code "Robert" -> "R163"}). Returns the empty string
 * when the name is {@code null} or contains no letters.
 */
static String soundex(String name) {
    if (name == null) {
        return "";
    }
    String letters = name.toUpperCase(java.util.Locale.ROOT).replaceAll("[^A-Z]", "");
    if (letters.isEmpty()) {
        return "";
    }
    StringBuilder code = new StringBuilder().append(letters.charAt(0));
    char previous = soundexCode(letters.charAt(0));
    for (int i = 1; i < letters.length() && code.length() < 4; i++) {
        char c = letters.charAt(i);
        if (c == 'H' || c == 'W') {
            continue;
        }
        char digit = soundexCode(c);
        if (digit != '0' && digit != previous) {
            code.append(digit);
        }
        previous = digit;
    }
    while (code.length() < 4) {
        code.append('0');
    }
    return code.toString();
}

/**
 * Maps a single upper-case letter to its Soundex digit, returning {@code '0'} for the vowels
 * {@code A,E,I,O,U,Y} and for {@code H,W} (which the caller handles specially).
 */
private static char soundexCode(char c) {
    return switch (c) {
        case 'B', 'F', 'P', 'V' -> '1';
        case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
        case 'D', 'T' -> '3';
        case 'L' -> '4';
        case 'M', 'N' -> '5';
        case 'R' -> '6';
        default -> '0';
    };
}

