            return null;
        }
        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
        String email = owner.getEmail() == null ? "" : owner.getEmail().trim().toLowerCase(java.util.Locale.ROOT);
        String soundex = soundex(owner.getLastName());
        return sha256Hex(telephone + "|" + email + "|" + soundex);
    }

    /**
     * Returns the full lower-case (64-character) SHA-256 hex digest of {@code value}'s UTF-8 bytes.
     * Deterministic, so the same input always yields the same digest.
     */
    static String sha256Hex(String value) {
        try {
            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
